import React from 'react';

interface Props {
  userId: number;
  name: string;
}

const UserCard = ({ userId, name }: Props) => {
  console.log('Rendering UserCard');
  return (
    <div className="user-card">
      <h3>{name}</h3>
      <p>User ID: {userId}</p>
    </div>
  );
